const FACES={"a_maserati":{"g":"","w":24,"h":32},"a_michelin":{"g":"","w":24,"h":32},"barnato":{"g":"","w":24,"h":32},"benoist":{"g":"","w":24,"h":32},"birkin":{"g":"","w":24,"h":32},"borghese":{"g":"","w":24,"h":32},"campari":{"g":"","w":24,"h":32},"campbell":{"g":"","w":24,"h":32},"caracciola":{"g":"","w":24,"h":32},"charron":{"g":"","w":24,"h":32},"chiron":{"g":"","w":24,"h":32},"de_dion":{"g":"","w":24,"h":32},"de_knyff":{"g":"","w":24,"h":32},"depalma":{"g":"","w":24,"h":32},"divo":{"g":"","w":24,"h":32},"edge":{"g":"","w":24,"h":32},"ferrari":{"g":"","w":24,"h":32},"fournier":{"g":"","w":24,"h":32},"g_boillot":{"g":"","w":24,"h":32},"goux":{"g":"","w":24,"h":32},"h_farman":{"g":"","w":24,"h":32},"h_ford":{"g":"","w":24,"h":32},"harroun":{"g":"","w":24,"h":32},"jellinek":{"g":"","w":24,"h":32},"jenatzy":{"g":"","w":24,"h":32},"junek":{"g":"","w":24,"h":32},"kl_guinness":{"g":"","w":24,"h":32},"l_chevrolet":{"g":"","w":24,"h":32},"lancia":{"g":"","w":24,"h":32},"lautenschlager":{"g":"","w":24,"h":32},"levassor":{"g":"","w":24,"h":32},"m_renault":{"g":"","w":24,"h":32},"materassi":{"g":"","w":24,"h":32},"murphy":{"g":"","w":24,"h":32},"nazzaro":{"g":"","w":24,"h":32},"nuvolari":{"g":"","w":24,"h":32},"oldfield":{"g":"","w":24,"h":32},"porsche":{"g":"","w":24,"h":32},"resta":{"g":"","w":24,"h":32},"rickenbacker":{"g":"","w":24,"h":32},"rolls":{"g":"","w":24,"h":32},"shaw":{"g":"","w":24,"h":32},"stuck":{"g":"","w":24,"h":32},"szisz":{"g":"","w":24,"h":32},"thery":{"g":"","w":24,"h":32},"vanderbilt":{"g":"","w":24,"h":32},"w_opel":{"g":"","w":24,"h":32},"wagner":{"g":"","w":24,"h":32},"winton":{"g":"","w":24,"h":32}};
// раскодировать один раз; оттенок волос — по верхней части снимка
function faceOf(id){const F=FACES[id];if(!F)return null;if(!F.px){try{const b=atob(F.g),n=b.length,a=new Uint8Array(n);for(let i=0;i<n;i++)a[i]=b.charCodeAt(i);F.px=a;
    let top=0,k=0;for(let j=0;j<4;j++)for(let i=6;i<18;i++){top+=a[j*F.w+i];k++;}top/=k*255;F.hair=top>0.62?'#8a8074':top>0.45?'#5a4028':'#241a14';
    // края снимка (фон, воротник) плавно уходят в тон щёк — на голове не видно «рамки»
    let m=0,q=0;for(let j=Math.round(F.h*0.35);j<Math.round(F.h*0.75);j++)for(let i=Math.round(F.w*0.25);i<Math.round(F.w*0.75);i++){m+=a[j*F.w+i];q++;}m/=q;F.mean=m;
    for(let j=0;j<F.h;j++)for(let i=0;i<F.w;i++){const x=((i+0.5)/F.w-0.5)/0.47,y=((j+0.5)/F.h-0.54)/0.52,r=Math.sqrt(x*x+y*y),w=Math.max(0,Math.min(1,(1.02-r)/0.3));a[j*F.w+i]=Math.round(m+(a[j*F.w+i]-m)*w);}}catch(_){return null;}}return F;}
